// @name Tap counter
// @background #1e1b4b
// @refresh 3600
// The smallest interactive UI: onClick changes a number, active: darkens the
// button under the finger, and frameos.remember keeps the count. The count is
// a signal: a tap runs only the <Count /> that reads it, not get().
const count = signal(0)
let loaded = false
const load = () => {
  if (!loaded) { loaded = true; count.value = frameos.recall('count') ?? 0 }
}
const set = (n) => { count.value = n; frameos.remember('count', n) }

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

const THEMES = {
  color: {
    page: 'bg-indigo-950 text-white',
    label: 'text-indigo-300',
    minus: 'bg-rose-500 active:bg-rose-700',
    plus: 'bg-emerald-500 active:bg-emerald-700',
    reset: 'px-5 py-3 bg-white/10 text-slate-300 active:bg-white/30',
  },
  high: {
    page: 'bg-white text-black',
    label: 'text-black',
    minus: 'bg-black',
    plus: 'bg-black',
    reset: 'px-[18px] py-[10px] bg-white border-2 border-black text-black',
  },
}

const Sign = ({ d, small }) => (
  <svg className={`${small ? 'w-8 h-8' : 'w-14 h-14'} text-white`} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round">
    <path d={d} />
  </svg>
)

const Count = memo(() => <span className="text-9xl font-bold">{`${count.value}`}</span>)
const SmallCount = memo(() => <span className="text-6xl font-bold">{`${count.value}`}</span>)

// On a round panel: the count in the middle of a ring of sixty ticks, one lit
// a tap (the way a stopwatch counts), the title in the arc above and the
// buttons in the arc below.
const RING = { color: { on: '#34d399', off: 'rgba(255,255,255,0.12)', down: '#fb7185' }, high: { on: '#000000', off: '#d4d4d4', down: '#000000' } }
const Ticks = memo(({ size, r, ring }) => {
  const n = count.value
  const lit = n === 0 ? 0 : ((Math.abs(n) - 1) % 60) + 1
  const c = size / 2
  return (
    <svg className={`absolute left-0 top-0 w-[${size}px] h-[${size}px]`} viewBox={`0 0 ${size} ${size}`}>
      {Array.from({ length: 60 }).map((_, i) => {
        // Clockwise from the top going up, the other way going down.
        const a = ((n < 0 ? -i : i) / 60) * Math.PI * 2
        const long = i % 5 === 0
        const r1 = r - (long ? r * 0.1 : r * 0.06)
        const sin = Math.sin(a), cos = Math.cos(a)
        return (
          <line x1={(c + sin * r1).toFixed(1)} y1={(c - cos * r1).toFixed(1)} x2={(c + sin * r).toFixed(1)} y2={(c - cos * r).toFixed(1)}
            stroke={i < lit ? (n < 0 ? ring.down : ring.on) : ring.off} strokeWidth={long ? 5 : 3} strokeLinecap="round" />
        )
      })}
    </svg>
  )
})
const RoundCount = memo(({ px }) => <span className={`text-[${px}px] leading-none font-bold`}>{`${count.value}`}</span>)

const getRound = (app, context, high) => {
  const t = high ? THEMES.high : THEMES.color
  const W = context.imageWidth, H = context.imageHeight
  const size = Math.min(W, H), r = size / 2
  const k = r / 240
  const px = (n) => Math.round(n * k)
  const box = (cy, h, w) => `absolute left-[${Math.round((size - w) / 2)}px] top-[${Math.round(r + cy - h / 2)}px] w-[${Math.round(w)}px] h-[${Math.round(h)}px] flex items-center justify-center`
  const button = px(92)
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
      <div className={`absolute left-[${(W - size) >> 1}px] top-[${(H - size) >> 1}px] w-[${size}px] h-[${size}px]`}>
        <Ticks size={size} r={r - Math.max(10, px(14))} ring={high ? RING.high : RING.color} />
        <div className={box(-r * 0.5, px(28), r)}>
          <span className={`text-[${Math.max(14, px(18))}px] uppercase font-semibold ${t.label}`}>Tap counter</span>
        </div>
        <div className={box(-r * 0.12, px(120), r * 1.4)}><RoundCount px={px(112)} /></div>
        <div className={box(r * 0.36, button, r * 1.3)}>
          <div className="flex items-center justify-between w-full">
            <div className={`w-[${button}px] h-[${button}px] rounded-full flex items-center justify-center ${t.minus}`} onClick={() => set(count.peek() - 1)}>
              <Sign d="M5 12h14" />
            </div>
            <div className={`w-[${button}px] h-[${button}px] rounded-full flex items-center justify-center ${t.plus}`} onClick={() => set(count.peek() + 1)}>
              <Sign d="M12 5v14M5 12h14" />
            </div>
          </div>
        </div>
        <div className={box(r * 0.68, px(48), r)}>
          <div className={`rounded-xl text-[${Math.max(14, px(18))}px] ${t.reset}`} onClick={() => set(0)}>Reset</div>
        </div>
      </div>
    </div>
  )
}

export function get(app, context) {
  load()
  if (context?.round === true) return getRound(app, context, highContrast(app))
  const t = highContrast(app) ? THEMES.high : THEMES.color
  // A small screen (a watch, a 2.8" panel, 240 px on a side): the same, smaller.
  // At full size it needs about 360 x 320 px, and the title and both buttons
  // fell off a 240 x 296 watch.
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  const small = W < 380 || H < 340
  const gap = small ? 'gap-3' : 'gap-6'
  const round = small ? 'w-16 h-16' : 'w-28 h-28'
  return (
    <div className={`flex flex-col items-center justify-center ${gap} ${t.page}`}>
      <span className={`${small ? 'text-sm' : 'text-lg'} uppercase font-semibold ${t.label}`}>Tap counter</span>
      {small ? <SmallCount /> : <Count />}
      <div className={`flex items-center ${gap}`}>
        <div className={`${round} rounded-full flex items-center justify-center ${t.minus}`} onClick={() => set(count.peek() - 1)}>
          <Sign d="M5 12h14" small={small} />
        </div>
        <div className={`rounded-xl ${small ? 'text-sm' : 'text-lg'} ${t.reset}`} onClick={() => set(0)}>Reset</div>
        <div className={`${round} rounded-full flex items-center justify-center ${t.plus}`} onClick={() => set(count.peek() + 1)}>
          <Sign d="M12 5v14M5 12h14" small={small} />
        </div>
      </div>
    </div>
  )
}
